"""
Git Pre-Commit & Pre-Push Hook Automator.
Generates, installs, and manages zero-dependency Git hooks for pre-flight repository reviews.
"""

import os
import stat
from typing import Dict, Tuple

HOOK_HEADER = "#!/bin/sh\n# Generated by PanelReview (AI Agent Panel Review System)\n# Do not edit manually below this line\n"

PRE_COMMIT_TEMPLATE = """#!/bin/sh
# Generated by PanelReview (AI Agent Panel Review System)
# Runs pre-flight multi-persona diff review and secret scan on staged changes before commit.

echo "🔍 [PanelReview] Running pre-commit validation on staged changes..."

# Verify python3 is available
if ! command -v python3 >/dev/null 2>&1; then
    echo "⚠️  [PanelReview] python3 not found. Skipping pre-commit hook."
    exit 0
fi

# Run fast diff review using mock/heuristic engine
python3 -m panel_review.cli review --diff --max-files 25
EXIT_CODE=$?

if [ $EXIT_CODE -ne 0 ]; then
    echo "❌ [PanelReview] Pre-commit review failed or found critical security/architecture issues."
    echo "   Fix the reported issues, or bypass with: git commit --no-verify"
    exit 1
fi

echo "✅ [PanelReview] Pre-commit check passed successfully!"
exit 0
"""

PRE_PUSH_TEMPLATE = """#!/bin/sh
# Generated by PanelReview (AI Agent Panel Review System)
# Runs pre-push repository review before pushing upstream.

echo "🚀 [PanelReview] Running pre-push panel review..."

if ! command -v python3 >/dev/null 2>&1; then
    echo "⚠️  [PanelReview] python3 not found. Skipping pre-push hook."
    exit 0
fi

python3 -m panel_review.cli review --path . --preset quick-scan
EXIT_CODE=$?

if [ $EXIT_CODE -ne 0 ]; then
    echo "❌ [PanelReview] Pre-push review failed."
    echo "   Fix the reported issues, or bypass with: git push --no-verify"
    exit 1
fi

echo "✅ [PanelReview] Pre-push check passed!"
exit 0
"""


class GitHookManager:
    """Installs and manages git hook automations."""

    @staticmethod
    def get_git_hooks_dir(repo_path: str = ".") -> str:
        """Resolves the .git/hooks directory for a repository."""
        git_dir = os.path.join(os.path.abspath(repo_path), ".git")
        if not os.path.isdir(git_dir):
            raise FileNotFoundError(f"Not a git repository (missing .git directory): {repo_path}")
        hooks_dir = os.path.join(git_dir, "hooks")
        os.makedirs(hooks_dir, exist_ok=True)
        return hooks_dir

    @classmethod
    def install_hook(cls, repo_path: str = ".", hook_type: str = "pre-commit") -> Tuple[bool, str]:
        """Installs a panel-review hook into the specified git repository."""
        if hook_type not in ("pre-commit", "pre-push"):
            return False, f"Unsupported hook type: '{hook_type}'. Must be 'pre-commit' or 'pre-push'."

        try:
            hooks_dir = cls.get_git_hooks_dir(repo_path)
            hook_file = os.path.join(hooks_dir, hook_type)

            content = PRE_COMMIT_TEMPLATE if hook_type == "pre-commit" else PRE_PUSH_TEMPLATE

            with open(hook_file, "w", encoding="utf-8") as f:
                f.write(content)

            # Make executable (chmod +x)
            st = os.stat(hook_file)
            os.chmod(hook_file, st.st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)

            return True, f"Successfully installed {hook_type} hook at {hook_file}"
        except Exception as e:
            return False, f"Failed to install {hook_type} hook: {str(e)}"

    @classmethod
    def uninstall_hook(cls, repo_path: str = ".", hook_type: str = "pre-commit") -> Tuple[bool, str]:
        """Uninstalls a panel-review hook if installed."""
        try:
            hooks_dir = cls.get_git_hooks_dir(repo_path)
            hook_file = os.path.join(hooks_dir, hook_type)

            if not os.path.exists(hook_file):
                return True, f"Hook {hook_type} does not exist at {hook_file}"

            with open(hook_file, "r", encoding="utf-8") as f:
                first_lines = f.read(250)

            if "PanelReview" not in first_lines:
                return False, f"Existing {hook_type} hook was not created by PanelReview; aborting for safety."

            os.remove(hook_file)
            return True, f"Successfully removed {hook_type} hook."
        except Exception as e:
            return False, f"Failed to uninstall hook: {str(e)}"

    @classmethod
    def status(cls, repo_path: str = ".") -> Dict[str, Dict]:
        """Returns the status of pre-commit and pre-push hooks."""
        res = {}
        try:
            hooks_dir = cls.get_git_hooks_dir(repo_path)
            for h in ("pre-commit", "pre-push"):
                file_path = os.path.join(hooks_dir, h)
                exists = os.path.exists(file_path)
                is_panel = False
                if exists:
                    try:
                        with open(file_path, "r", encoding="utf-8") as f:
                            is_panel = "PanelReview" in f.read(250)
                    except Exception:
                        pass
                res[h] = {"exists": exists, "is_panel_review": is_panel, "path": file_path}
        except Exception as e:
            res["error"] = str(e)
        return res
